'use strict';
(()=>{
 const article=document.createElement('article');article.className='panel';article.innerHTML='<div class="panel-head"><div><h2>家庭支出构成</h2><p>所选期间内，各成员已录月总额的占比。</p></div></div><div class="income-composition"></div>';$('expenseReportPanel').after(article);const box=article.lastElementChild;
 function render(){if(!D.live||!current)return;box.replaceChildren();const e=current.familyExpense,profiles=(D.memberProfiles||[]).filter(p=>p.active),groups=new Map();for(const b of e.byMember){const p=profiles.find(p=>p.key===b.name),key=p?p.key:b.name==='共同'?'共同':'历史其他支出';groups.set(key,(groups.get(key)||0)+b.cents);}if(!groups.size){box.textContent='所选期间尚无可完整计入的月度支出；未填月份不会补0。';return;}if([...groups.values()].some(v=>v<0)){box.textContent='包含退款冲减后的负支出，无法用饼图表达占比，请查看支出曲线和明细。';return;}const total=[...groups.values()].reduce((a,b)=>a+b,0);if(!total){box.textContent='所选期间已录净支出合计为0。';return;}const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 260 260');svg.classList.add('income-donut');svg.setAttribute('role','img');svg.setAttribute('aria-label','家庭支出构成');const legend=document.createElement('div');legend.className='composition-legend';const tip=document.createElement('p');tip.className='composition-tip';tip.setAttribute('role','status');tip.textContent='点击或悬停查看金额与占比';let offset=0;
 for(const [key,cents]of groups){if(!cents)continue;const p=profiles.find(p=>p.key===key),name=p?p.name:key==='共同'?'未拆分家庭支出':key,color=p?FamilyChartAxis.memberColor(p,profiles.indexOf(p)):'#8d929f',share=cents/total,text=name+'：'+money(cents)+' · '+(share*100).toFixed(1)+'%';const circle=document.createElementNS(svg.namespaceURI,'circle');for(const [k,v]of Object.entries({cx:130,cy:130,r:90,fill:'none',stroke:color,'stroke-width':30,pathLength:100,'stroke-dasharray':share*100+' '+(100-share*100),'stroke-dashoffset':-offset,transform:'rotate(-90 130 130)',tabindex:0,'aria-label':text}))circle.setAttribute(k,v);circle.onpointerenter=circle.onfocus=circle.onclick=()=>tip.textContent=text;svg.append(circle);offset+=share*100;const b=document.createElement('button');b.className='composition-member';b.type='button';const dot=document.createElement('i');dot.style.background=color;const label=document.createElement('span');label.textContent=name;const value=document.createElement('strong');value.textContent=money(cents)+' · '+(share*100).toFixed(1)+'%';b.append(dot,label,value);b.onclick=()=>tip.textContent=text;legend.append(b);}
 const label=document.createElementNS(svg.namespaceURI,'text');label.setAttribute('x','130');label.setAttribute('y','135');label.setAttribute('text-anchor','middle');label.setAttribute('fill','currentColor');label.setAttribute('font-size','20');label.textContent=money(total);svg.append(label);box.append(svg,legend,tip);const note=document.createElement('p');note.className='muted full';note.textContent=e.unresolved.length?'有月总额被日期边界截断，图表仅含可完整定位的月份。':'只统计已录支出；没有分人数据的月份单独显示，不自动摊给成员。';box.append(note);
 }
 const prior=render;window.FamilyExpenseComposition={render};const old=window.FamilyInline.draw;window.FamilyInline.draw=()=>{old();render();};const baseRender=window.render;window.render=function(){baseRender();render();};document.addEventListener('family-ledger-ready',render);window.addEventListener('hashchange',render);if(D.live)prior();
})();
